# Flat view — scene_key → scene_prompt. Derived from SETTINGS so a single
# authoring source stays canonical. Kept under the old `CONTENTS` name so
# existing consumers (build_scene_prompt, levelbuilder, etc.) don't break.
CONTENTS = {
    scene_key: scene_prompt for setting in SETTINGS.values() for scene_key, scene_prompt in setting["scenes"].items()
}

SCENE_TITLES = {
    scene_key: scene_key.removeprefix(f"{setting_key}_").replace("_", " ").title()
    for setting_key, setting in SETTINGS.items()
    for scene_key in setting["scenes"]
}


def _scene_title(scene_key: str) -> str:
    return SCENE_TITLES.get(scene_key, scene_key.replace("_", " ").title())


def _short_scene_description(scene_key: str, scene_prompt: str) -> str:
    """Return a compact one-sentence description for prompt context.

    The v4 background prompts carry a short level description that helps
    downstream crop planning understand the world before reading the full
    art brief. For the older country catalogue, derive that sentence from
    the first scene sentence so the data stays single-source.
    """
    first_sentence = scene_prompt.split(". ", 1)[0].strip()
    subject = first_sentence.split(" — ", 1)[0].strip()
    if not subject:
        subject = _scene_title(scene_key)
    if subject.endswith("."):
        subject = subject[:-1]
    return f"{subject} arranged as an organic isometric hidden-object scene."


SCENE_DESCRIPTIONS = {
    scene_key: _short_scene_description(scene_key, scene_prompt)
    for scene_key, scene_prompt in CONTENTS.items()
}

# Collectible entity types. Game code + on-disk layout stay "dog"-named
# for backward compat; the `entity` parameter controls the image we paint
# into each hitbox. Keys are slugs used by the builder / CLI; values are
# the noun phrase substituted into ENTITY_PROMPT_TEMPLATE below.
ENTITIES = {
    "dog": "dog",
    "cat": "cat",
    "capybara": "capybara",
    "teddy_bear": "teddy bear plush toy",
    "bird": "bird",
}

# Style-specific entity prompt overrides. When a (style, entity) pair needs
# fully bespoke phrasing (rather than the universal template with a noun
# substituted), it lives here and wins over ENTITY_PROMPT_TEMPLATE.
ENTITY_STYLE_PROMPTS = {
    "bold_cardboard": {
        "bird": (
            "Add exactly one charming stylized storybook bird to this crop, centered on the "
            "marked target area. Render it from bold flat-shaded matte cardstock and thin "
            "cardboard layers with crisp die-cut edges, large readable shapes, calm solid "
            "colors, and controlled cast shadows matching the scene. Use a varied natural bird "
            "palette across the level while keeping strong local contrast. The bird may wear "
            "one simple explorer accessory or use a scene-appropriate tool, but it must have "
            "exactly two wings and two legs with no separate human arms, hands, fingers, or "
            "realistic avian anatomy. A folded wing may gesture around a tool; straps, beak, "
            "perch, or the environment may support objects. Give the bird one clear, quiet "
            "activity or expression appropriate to its hiding place. Keep it partially "
            "discoverable rather than erased by camouflage: no muddy edges, texture noise, or "
            "ambiguous merged shapes. It must be fully contained in frame and sized "
            "consistently with nearby props. Replace only the marked area and preserve the "
            "surrounding scene. No felt, fabric, fuzz, stitching, embroidery, plush, wool, "
            "photorealism, glossy plastic, text, logos, or watermark."
        ),
    },
}

# Universal entity prompt template. Count constraint leads because it's
# the most ignored instruction. Size anchor is a single concrete object
# (bench / barrel) so the instruction works even when the crop doesn't
# contain the props the old version compared against. The behavioral
# layer ("anthropomorphic inhabitant going about its business") landed
# after testing showed animals placed without behavioral direction came
# out as static pets; fully-dynamic poses broke anatomy at small scales,
# so the register is chill-with-action rather than mid-leap.
ENTITY_PROMPT_TEMPLATE = (
    "Add exactly one {entity} to this crop. Place exactly one {entity} centered on the marked "
    "target area — do not repeat the subject. Match the scene's illustration style, line weight, "
    "palette, and flat-shaded rendering, but keep the {entity}'s silhouette and boundary readable "
    "on a phone screen. The {entity} may be partially occluded or contextually disguised, but must "
    "not disappear through muddy edges, low contrast, texture camouflage, or ambiguous merged "
    "shapes. "
    "Vary the {entity}'s colors, markings, proportions, and small physical details across "
    "crops so the level does not repeat the same {entity} design. "
    "The {entity} is a charming little anthropomorphic inhabitant of this world — a character "
    "with personality going about its business. Give it something simple and specific to do with "
    "its surroundings: holding an object, using a tool, sitting at a small task, peeking at "
    "something, carrying something, watching something with interest, tending a small thing, "
    "pausing mid-task. Keep the pose clear and readable. The charm comes from the context and the "
    "expression, not from dynamic motion. "
    "Size the {entity} realistically relative to the scene around it — compare it to whatever "
    "human-scale objects are visible in the crop and render the {entity} at the physical size "
    "a real {entity} would be next to them. Not so small that its species is ambiguous, not so "
    "large that it dominates the crop. "
    "The {entity} must be fully contained within the visible frame. Keep all other elements of "
    "the image unchanged."
)

# `old_pixel_art` keeps its archived original phrasing for the legacy assets
# that were generated with it — kept explicit so an A/B against the new prompt
# isolates the prompt change from the rendering change.
_OLD_PIXEL_ART_ENTITY_PROMPT_TEMPLATE = (
    "Replace the center of this image with a {entity}. "
    "8-bit pixel sprite style, flat colors, black outline, no anti-aliasing. "
    "The {entity} should be blending in to the background. "
    "It can be doing something related to the background. "
    "If there is a chair sitting on it, if there is a window leaning outside of it. "
    "Preserve the background exactly."
)


def get_entity_prompt(style: str = "clean_old_cartoon", entity: str = "dog") -> str:
    """Compose the inpaint prompt for a given style + entity type.

    The style chooses between the modern universal template (style read
    from the surrounding image, no prose) and the legacy `old_pixel_art`
    phrasing (keeps its own baked-in style words for archival assets).
    The entity slug is looked up in ENTITIES; custom strings pass through.
    """
    noun = ENTITIES.get(entity, entity)
    styled_prompt = ENTITY_STYLE_PROMPTS.get(style, {}).get(entity)
    if styled_prompt is not None:
        return styled_prompt
    if style == "old_pixel_art":
        return _OLD_PIXEL_ART_ENTITY_PROMPT_TEMPLATE.format(entity=noun)
    return ENTITY_PROMPT_TEMPLATE.format(entity=noun)


# Backward-compat aliases: callers that don't care about entity type still
# get a valid "dog" prompt without plumbing the new parameter through.
# DOG_PROMPTS is kept — three tool scripts look up by style: `DOG_PROMPTS[style]`.
# The singular `DOG_PROMPT` constant had no callers and was removed.
DOG_PROMPTS = {slug: get_entity_prompt(slug, "dog") for slug in STYLES}


def build_scene_prompt(
    view: str = "isometric",
    style: str = "clean_old_cartoon",
    content: str = "istanbul_market",
    entity: str = "dog",
) -> str:
    """Compose a scene prompt from view + style + content.

    All three are independently swappable. Pass custom strings
    for any parameter to override the defaults.

    >>> build_scene_prompt("isometric", "pixelart", "istanbul_market")
    'A bustling Istanbul market... Isometric 45-degree... Chunky pixel art... No animals, no people.'
    """
    v = VIEWS.get(view, view)
    s = STYLES.get(style, style)
    c = CONTENTS.get(content, content)
    title = _scene_title(content)
    short_description = _short_scene_description(content, c)
    entity_noun = ENTITIES.get(entity, entity)
    game_title = f"Find the {entity_noun.title()}"
    target_plural = f"{entity_noun}s"
    return "\n\n".join(
        [
            f"[Purpose]\nCreate a full-bleed mobile-game background for {game_title}.",
            f"[Short Description]\n{short_description}",
            f"[Scene]\n{c}",
            f"[View]\n{v}",
            f"[Style]\n{s}",
            (
                "[Gameplay Composition]\n"
                f"Design this as a production hidden-object background where {target_plural} will be added later. "
                "Create many plausible hiding pockets on walkable/contact surfaces or open gaps beside "
                "props, plants, rocks, furniture, railings, crates, planters, benches, roots, tools, "
                "shelves, stalls, boats, carts, market goods, or other readable foreground objects. "
                "Near props is ideal; inside solid objects, on blank walls, on roofs, floating over "
                "water, or on decorative vertical faces is not useful. Use theme-specific spatial logic "
                "such as rings, islands, terraces, nested rooms, clearings, bridges, piers, shelves, "
                "courtyards, side alleys, garden pockets, or clustered market zones. Keep open pockets "
                "between prop clusters so hitboxes can sit near objects without excessive overlap."
            ),
            (
                "[Constraints]\n"
                f"Do not depict any {entity_noun}; every {entity_noun} is added during the later gameplay pass. "
                "No people, no live animals, no insects, no mascots, no readable "
                "text, no logos, no watermarks. Signs, chalkboards, labels, plaques, and boards "
                "named in the scene may appear but must show only illegible marks, squiggles, or "
                "blank surfaces — never legible words or letters. "
                "Market food and fishing props are allowed when the scene calls for them. Avoid huge blank walls, roof-dominated compositions, "
                "large featureless empty lawns, empty sand, empty floors, long straight roads, and noisy micro-texture "
                "camouflage. Every visible ground, floor, or water-edge region should read as a clear "
                "material appropriate to the scene; no untextured blank areas."
            ),
        ]
    )


def get_dog_prompt(style: str = "clean_old_cartoon") -> str:
    """Get the style-matched dog inpainting prompt.

    Backward-compat wrapper around get_entity_prompt(style, "dog").
    """
    return get_entity_prompt(style, "dog")


# ── Meta prompts used by the level-builder web app ────────────────────────────

# System prompt for the "generate a unique scene variation" LLM call.
# Given (view, style, content), the builder asks a small model to produce a
# concrete 2-3 sentence scene description so levels with the same theme feel
# distinct. Centralised here so tooling stays aligned.
VARIATION_SYSTEM_PROMPT = (
    "You are a scene description generator for a hidden-object puzzle game. "
    "Given a general scene description (content, perspective, art style), generate a SPECIFIC, UNIQUE "
    "variation of that scene with concrete details — specific objects, colors, arrangements, landmarks, "
    "and atmospheric details that make this particular level distinct from others with the same theme. "
    "Do NOT mention dogs or animals — they will be added separately. "
    "Output EXACTLY two lines in this format (no preamble, no extra lines, no markdown):\n"
    "TITLE: <2-4 word evocative title in Title Case>\n"
    "SCENE: <2-3 sentence scene description>"
)

# Prefix wrapped around landscape scene prompts so the resulting 16:9
# background reads as one continuous wide panorama. Used by both the CLI
# landscape generator and the builder UI.
LANDSCAPE_PANORAMIC_PREFIX = (
    "Wide panoramic 16:9 widescreen composition designed for a horizontally-panning camera. "
    "The scene extends across three distinct visual sections from left to right — "
    "a left zone with its own anchoring feature, a central zone with a hinge feature, "
    "a right zone with its own anchoring feature. "
    "A continuous horizontal spine runs across all three sections — a path, canal, river, "
    "road, shoreline, or architectural line — so the image reads as one continuous place, "
    "not three separate panels. "
    "Composition distributes visual weight evenly across the full width, with density and "
    "interest spread left-to-right rather than concentrated at the center. "
    "The top and bottom strips of the frame stay visually simpler, keeping critical detail "
    "in the middle band where gameplay happens. "
)


